"""ONE A100 Colab cell: native weights 100/500 x LR trajectories 100/500, all fresh AdamW.
3900 total updates: 1500 native-only starting-state + 2400 matched branch updates.
No old checkpoint ZIP needed. Pinned fingerprints verify native trunks and the early diagonal against prior runs.
Reset moments/counters; transplant the selected external LR scheduler without restarting warmup.
Identical processed continuation batches and RNG across all weight/LR/treatment cells.
512 report images excluded from all new training/probes; NOT a new external dataset.
Requires torch 2.11.0+cu128 / torchvision 0.26.0+cu128; 15 GiB free runtime disk.
Prefer high-RAM. Starting snapshots remain in RAM; endpoint embeddings saved to Drive.
Paste the ENTIRE file. Wait for DRIVE_SYNC_COMPLETE. No automatic retries/resume.
"""
import base64
from datetime import datetime, timezone
import hashlib
import importlib.util
import json
from pathlib import Path
import subprocess
import sys
import tempfile
import zlib

BASE_COMMIT = 'b36bcbf7c2124bbcbe0cf372df3853dadcf79bd2'
BUNDLE_SHA256 = '9d1f48b37336cc190ad7be33ce77dbc325bc1f7422e0742ab86d26bba9bc07b0'
PAYLOAD = ''

def run_all():
    if not Path('/content').is_dir():
        raise RuntimeError('Run in Google Colab with one A100 GPU.')
    raw = zlib.decompress(base64.b64decode(PAYLOAD))
    if hashlib.sha256(raw).hexdigest() != BUNDLE_SHA256:
        raise RuntimeError('Embedded bundle checksum mismatch')
    from google.colab import drive
    drive.mount('/content/drive')
    staging = Path(tempfile.mkdtemp(prefix='otco_weight_lr_source_',dir='/content'))
    repo = staging/'repo'
    subprocess.run(['git','clone','--no-checkout','https://github.com/akashm776/otco.git',str(repo)],check=True)
    subprocess.run(['git','-C',str(repo),'checkout','--detach',BASE_COMMIT],check=True)
    if subprocess.check_output(['git','-C',str(repo),'rev-parse','HEAD'],text=True).strip() != BASE_COMMIT:
        raise RuntimeError('Wrong pinned repository base')
    for name,source in json.loads(raw).items():
        path = Path(name)
        if path.is_absolute() or '..' in path.parts:
            raise RuntimeError('Unsafe source overlay path')
        target = repo/path
        target.parent.mkdir(parents=True,exist_ok=True)
        target.write_text(source,encoding='utf-8')
    spec = importlib.util.spec_from_file_location('otco_weight_lr_logging',repo/'colabs/policy_test_logging.py')
    logger = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(logger)
    stamp = datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S_%fZ')
    log = Path('/content/drive/MyDrive/OTCO/evaluation_transfer/clip_weight_lr_logs')/(stamp+'.log')
    print('FULL_SUBPROCESS_LOG:',log,flush=True)
    try:
        logger.run_logged([sys.executable,'-u',str(repo/'colabs/run_clip_weight_lr.py'),
                           '--bundle-id',BUNDLE_SHA256],repo,log)
    except BaseException:
        print('WEIGHT_LR_FAILED: inspect full log; do not restart automatically.')
        try:
            drive.flush_and_unmount()
            print('PARTIAL_DRIVE_SYNC_COMPLETE: this does NOT mean the experiment completed.')
        except BaseException as error:
            print('DRIVE_FLUSH_FAILED:',repr(error))
        raise
    drive.flush_and_unmount()
    print('DRIVE_SYNC_COMPLETE: weight-LR results and log saved; Drive now unmounted.')
    print('Download the new clip_weight_lr run folder and its log. No large checkpoints written.')

run_all()
